// 抓包数据已解析好：先按「交易编号 + 行ID」去重，再按列表的「商品个数」剔除重复行
const seen = new Set();
let rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.SKU) continue;
  const lineId = j['行ID'] || '';
  const key = lineId ? `${j.交易编号}|${lineId}` : `${j.交易编号}|${j.SKU}|${rows.length}`;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push(j);
}

// 同一交易编号出现多个平台单号（拆分单）→ 只保留平台单号带 _1 的那单
{
  const idsOf = new Map();
  for (const r of rows) {
    const t = String(r['交易编号']);
    const pid = String(r['订单编号'] || '');
    if (!idsOf.has(t)) idsOf.set(t, new Set());
    idsOf.get(t).add(pid);
  }
  const keepSet = new Set();
  let dropped = 0;
  const before = rows.length;
  rows = rows.filter(r => {
    const t = String(r['交易编号']);
    const ids = idsOf.get(t);
    if (!ids || ids.size <= 1) return true;
    const hasSplit = [...ids].some(x => x.includes('_1'));
    if (!hasSplit) return true;
    const ok = String(r['订单编号'] || '').includes('_1');
    if (!ok) dropped++;
    return ok;
  });
  if (dropped) console.log('拆分单去重：丢弃 ' + dropped + ' 行（' + before + '→' + rows.length + '）');
}

// 每个订单实际应有多少件（来自 ERP 列表的 (商品种类:N;商品个数:M)）
const want = new Map();
try {
  for (const it of $('Code in JavaScript2').all()) {
    const j = it.json || {};
    const n = j['商品个数'];
    if (j['交易编号'] && n !== null && n !== undefined && !isNaN(Number(n))) {
      want.set(String(j['交易编号']), Number(n));
    }
  }
} catch (e) {}

// 明细件数超过「商品个数」→ 去掉完全重复的行（同 SKU + 同件数）
const byTxn = new Map();
for (const r of rows) {
  const t = String(r['交易编号']);
  if (!byTxn.has(t)) byTxn.set(t, []);
  byTxn.get(t).push(r);
}
const out = [];
for (const [t, list] of byTxn) {
  const w = want.get(t);
  const sumOf = (arr) => arr.reduce((s, x) => s + Number(x['商品数量'] || 0), 0);
  let keep = list;
  if (w !== undefined && sumOf(list) > w) {
    const used = new Map();
    const kept = [];
    for (const r of list) {
      const k = `${r.SKU}|${r['商品数量']}`;
      const u = used.get(k) || 0;
      const cur = sumOf(kept);
      if (u + Number(r['商品数量'] || 0) <= w - cur) {
        kept.push(r);
        used.set(k, u + Number(r['商品数量'] || 0));
      }
    }
    if (kept.length && sumOf(kept) === w) keep = kept;
  }
  out.push(...keep);
}
if (!out.length) throw new Error('没有解析到任何订单明细');
console.log('订单', byTxn.size, '| 明细行', out.length);
return out.map(j => ({ json: j }));

let form = null;
try { form = $('解析表单输入').first().json; } catch (e) { form = null; }

if (!form) {
  return { mode: 'dates', startDate: '2026-11-09 00:00:00', endDate: '2026-11-12 00:00:00', noteSuffix: '' };
}
if (!form.ok) throw new Error('表单输入有误：' + (form.errors || []).join('；'));
return {
  mode: form.mode,
  窗口开始: form.窗口开始,
  窗口结束: form.窗口结束,
  startDate: form.开始日期,
  endDate: form.结束日期,
  chunks: form.chunks || [],
  noteSuffix: form.noteSuffix || '',
};

const cfg = $input.first().json;

// 按交易编号查：每个批次一条请求（每批最多 10 个）
if (cfg.mode === 'numbers') {
  // ERP 要求必须带时间：按天拆，每天带单号过滤，窗口 = 今天往前 7 天
  const chunks = cfg.chunks || [];
  if (!chunks.length) throw new Error('没有有效的交易编号');
  // 窗口缺失时兜底：今天往前 7 天（北京时间）
  const windowFallback = () => {
    const now = new Date(Date.now() + 8 * 3600 * 1000);
    const p2 = (x) => String(x).padStart(2, '0');
    const f = (d) => `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}`;
    return { s: f(new Date(now.getTime() - 7 * 86400000)), e: f(now) };
  };
  const fb = windowFallback();
  const s = new Date(((cfg.窗口开始 || fb.s) + 'T00:00:00Z'));
  const e = new Date(((cfg.窗口结束 || fb.e) + 'T00:00:00Z'));
  const days = [];
  if (!isNaN(s) && !isNaN(e)) {
    for (let d = new Date(s); d <= e; d = new Date(d.getTime() + 86400000)) {
      days.push(d.toISOString().slice(0, 10));
    }
  }
  if (!days.length) throw new Error('查询窗口为空');
  const out = [];
  for (const day of days) {
    for (let i = 0; i < chunks.length; i++) {
      out.push({ json: {
        批次: i + 1,
        日期: day,
        salesRecordNumbers: chunks[i].join(','),
        api_start_time: `${day} 00:00:00`,
        api_end_time: `${day} 23:59:59`,
        noteSuffix: cfg.noteSuffix || '',
      } });
    }
  }
  return out;
}

// 按时间段查：按天拆成多条请求
const startRaw = cfg.startDate;
const endRaw = cfg.endDate;

const pad2 = (n) => String(n).padStart(2, '0');

function parseDateTime(str) {
  // 兼容 2026-5-4、2026/5/4、2026-5-4 9:5:3、2026-05-04 09:05:03 等
  const m = String(str).trim().match(
    /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/
  );

  if (!m) {
    throw new Error(`无法解析日期时间: ${str}`);
  }

  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const hour = m[4] !== undefined ? Number(m[4]) : 0;
  const minute = m[5] !== undefined ? Number(m[5]) : 0;
  const second = m[6] !== undefined ? Number(m[6]) : 0;

  const dateStr = `${year}-${pad2(month)}-${pad2(day)}`;
  const dateTimeStr = `${dateStr} ${pad2(hour)}:${pad2(minute)}:${pad2(second)}`;

  return {
    year,
    month,
    day,
    hour,
    minute,
    second,
    dateStr,
    dateTimeStr
  };
}

const start = parseDateTime(startRaw);
const end = parseDateTime(endRaw);

// 使用 UTC 日期，避免时区导致日期错乱
let current = new Date(Date.UTC(start.year, start.month - 1, start.day));
const endDate = new Date(Date.UTC(end.year, end.month - 1, end.day));

const dateItems = [];

while (current <= endDate) {
  const currentDayStr = [
    current.getUTCFullYear(),
    pad2(current.getUTCMonth() + 1),
    pad2(current.getUTCDate())
  ].join('-');

  let dayStart;
  if (currentDayStr === start.dateStr) {
    // 第一天：使用传入的开始时间，统一补零格式化
    dayStart = start.dateTimeStr;
  } else {
    dayStart = `${currentDayStr} 00:00:00`;
  }

  let dayEnd;
  if (currentDayStr === end.dateStr) {
    // 最后一天：使用传入的结束时间，统一补零格式化
    dayEnd = end.dateTimeStr;
  } else {
    dayEnd = `${currentDayStr} 23:59:59`;
  }

  dateItems.push({
    json: {
      api_start_time: dayStart,
      api_end_time: dayEnd
    }
  });

  current.setUTCDate(current.getUTCDate() + 1);
}

return dateItems;

const arr = $input.all().map(item=>{
  console.log(item.json.data.data)
  return item.json.data.data
}).flat(Infinity)

// console.log(arr)

return arr

// ============================================================================
// 提取澳大利亚邮编（去重，只查这些邮编，避免全表 9091 行）
//   输入：「解析出需要的数据」的订单明细
//   输出：每个唯一邮编一个 item，下游按邮编单条查询分区
// ============================================================================
// 订单明细固定从「解析出需要的数据」取（上游是通知节点，$input 不可用）
let rows = [];
for (const src of ['解析出需要的数据', '合并澳洲分区']) {
  try {
    const got = $(src).all().map(i => i.json).filter(r => r && r.SKU);
    if (got.length) { rows = got; break; }
  } catch (e) { /* 该节点未执行，换下一个 */ }
}
if (!rows.length) rows = $input.all().map(i => i.json).filter(r => r && r.SKU);


const set = new Set();
for (const r of rows) {
  if (String(r['国家中文'] || '').trim() !== '澳大利亚') continue;
  const pc = String(r['邮政编码'] || '').replace(/\D/g, '').padStart(4, '0').slice(-4);
  if (pc.length === 4) set.add(pc);
}

// 没有澳洲单也要输出 1 条，否则下游节点不会执行、整条链断掉
if (!set.size) set.add('__NONE__');

return [...set].map(pc => ({ json: { 邮编: pc } }));

// ============================================================================
// 合并澳洲分区：把「查询澳大利亚分区表」的结果拼回订单
//   输出：订单明细（原样）+ 澳洲邮编 / 澳洲分区
// ============================================================================
const map = new Map();

for (const it of $('查询澳大利亚分区表').all()) {
  for (const rec of (it.json.items || [])) {
    const f = rec.fields || {};
    let pc = f['邮编'];
    if (Array.isArray(pc)) pc = (pc[0] && (pc[0].text ?? pc[0])) ?? '';
    pc = String(pc ?? '').trim().padStart(4, '0');

    let zone = f['分区'];
    if (zone && typeof zone === 'object') zone = zone.value ?? zone;

    if (pc.length === 4 && zone !== null && zone !== undefined && zone !== '' && !map.has(pc)) {
      map.set(pc, Number(zone));
    }
  }
}

const rows = $('解析出需要的数据').all().map(i => i.json).filter(r => r && r.SKU);

return rows.map(r => {
  const o = { ...r };
  if (String(o['国家中文'] || '').trim() === '澳大利亚') {
    const pc = String(o['邮政编码'] || '').replace(/\D/g, '').padStart(4, '0').slice(-4);
    o['澳洲邮编'] = pc;
    o['澳洲分区'] = map.has(pc) ? map.get(pc) : null;
  }
  return { json: o };
});

// 飞书记录 → 扁平对象
function flattenValue(v) {
  if (v === null || v === undefined) return null;
  if (typeof v !== 'object') return v;
  if (Array.isArray(v)) {
    return v.map(x => (x === null || x === undefined) ? ''
      : (typeof x === 'object' ? (x.text ?? x.name ?? '') : String(x))).join('');
  }
  return v.text ?? v.name ?? '';
}
const items = $input.first().json.items || [];
return items.map(r => {
  const o = { record_id: r.record_id };
  for (const [k, v] of Object.entries(r.fields || {})) o[k] = flattenValue(v);
  return { json: o };
});

// 纯 JS 的 UTF-8 → Base64（不依赖 Node 全局，避免 Code 节点 TS 报错）
function utf8Bytes(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return out;
}
function toBase64(str) {
  const CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const b = utf8Bytes(str);
  let s = '';
  for (let i = 0; i < b.length; i += 3) {
    const b1 = b[i], b2 = b[i + 1], b3 = b[i + 2];
    s += CH[b1 >> 2];
    s += CH[((b1 & 3) << 4) | ((b2 ?? 0) >> 4)];
    s += (i + 1 < b.length) ? CH[((b2 & 15) << 2) | ((b3 ?? 0) >> 6)] : '=';
    s += (i + 2 < b.length) ? CH[b3 & 63] : '=';
  }
  return s;
}

// 备注后缀（表单没跑时也不报错）
let noteSuffix = '';
try { noteSuffix = $('解析表单输入').first().json.noteSuffix || ''; } catch (e) {}

// 把匹配结果整理成「写表用」的 JSON
const d = $('⑥ 异常汇总消息').first().json;
const ts = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace(/[-:T]/g, '').slice(0, 14);

// 明细顺序：按「交易编号第一次出现」的顺序（表单填写顺序 > 订单列表顺序）
function orderKey() {
  const map = new Map();
  const push = (v) => {
    const s = String(v ?? '').trim();
    if (s && !map.has(s)) map.set(s, map.size);
  };
  // 1) 表单里填的交易编号（按填写顺序）
  try {
    const f = $('解析表单输入').first().json || {};
    String(f.id || '').split(/[,，;；\s]+/).forEach(push);
  } catch (e) {}
  // 2) 兜底：订单明细里出现的顺序
  for (const r of (d.detail || [])) push(r['交易编号']);
  return map;
}
const __pos = orderKey();
const __detail = (d.detail || []).slice().sort((a, b) => {
  const ia = __pos.has(String(a['交易编号'])) ? __pos.get(String(a['交易编号'])) : 1e9;
  const ib = __pos.has(String(b['交易编号'])) ? __pos.get(String(b['交易编号'])) : 1e9;
  return ia - ib;
});

const payload = {
  detail: __detail,
  missingList: d.missingList || [],
  params: (() => {
    let prev = 0;
    try { prev = Number($('解析表单输入').first().json['上期余额']) || 0; } catch (e) {}
    return { ...(d.params || {}), PREV_BALANCE: prev };
  })(),
  totals: d.totals || {},
};

return [{
  json: {
    detailPath: `/data/data/workflow005/logs/bill_detail_${ts}.json`,
    outPath: `/data/data/workflow005/output/60103计算表_${ts}${noteSuffix}.xlsx`,
    rows: (d.detail || []).length,
    orders: d.totalOrders,
  },
  binary: {
    data: {
      data: toBase64(JSON.stringify(payload)),
      mimeType: 'application/json',
      fileName: 'bill_detail.json',
    },
  },
}];

// 只解析计算表（PDF 暂时停用）
const parse = (resp) => {
  const out = ((resp && resp.stdout) || '').trim();
  const err = ((resp && resp.stderr) || '').trim();
  const line = out.split('\n').find(l => l.startsWith('RESULT '));
  const res = line ? JSON.parse(line.slice(7)) : {};
  return { out, err, code: resp ? resp.code : -1, res };
};

const x = parse($json);
if (x.code !== 0) throw new Error('写表失败：' + x.err.split('\n').slice(-6).join(' | '));

return [{ json: {
