const ts = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace(/[-:T]/g, '').slice(0, 14);
// 纯 JS 的 UTF-8 → Base64（不依赖 Node 全局，避免 Code 节点 TS 报错）
function utf8Bytes(str) {
