}

const base = '/data/data/workflow005';
let noteSuffix = '';
try { noteSuffix = $('解析表单输入').first().json.noteSuffix || ''; } catch (e) {}

return [{
  json: {
    jsonPath: `${base}/logs/orders_run_${ts}.json`,
    xlsxPath: `${base}/input/订单导出_${ts}${noteSuffix}.xlsx`,
    rows: rows.length,
