    data: {
      data: toBase64(JSON.stringify({ rows })),
      mimeType: 'application/json',
      fileName: 'orders_run.json',
    },
  },
}];

// ① 建配置索引（v7：商品按前缀；运价按国家 + 重量段）
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// ---------- 商品（一行一个前缀）----------
const products = {};
const productMissing = [];
for (const r of $('解析商品表').all().map(i => i.json)) {
  const p = String(r['SKU前缀'] ?? '').trim();
  if (!p || p.startsWith('(待补)')) continue;
  const v = {
    采购价: num(r['采购价']), 国内运费: num(r['国内运费']) ?? 0, 重量: num(r['重量(kg)']),
    服务费: num(r['服务费']),
    商品中文名: String(r['商品中文名'] ?? '').trim(),
  };
  products[p] = v;
  const lack = [];
  if (v.采购价 === null) lack.push('采购价');
  if (v.重量 === null) lack.push('重量');
  if (lack.length) productMissing.push({ 前缀: p, 商品中文名: v.商品中文名, 缺: lack });
}

// ---------- 运价：国家 → [段] ----------
const byCountry = new Map();
const rateMissing = [];
for (const r of $('解析运价表').all().map(i => i.json)) {
  const c = String(r['国家'] ?? '').trim();
  if (!c) continue;
  const lo = num(r['下界']), hi = num(r['上界']), p = num(r['公斤价']), fee = num(r['挂号费']);
  if (lo === null || hi === null || p === null || fee === null) { rateMissing.push({ 国家: c, 段: `${r['下界'] ?? '?'}~${r['上界'] ?? '?'}` }); continue; }
  if (!byCountry.has(c)) byCountry.set(c, []);
  byCountry.get(c).push({ 国家: c, 线路: String(r['线路'] ?? '').trim(), lo, hi, p, fee, 毛利: num(r['毛利']) });
}
for (const arr of byCountry.values()) arr.sort((a, b) => a.lo - b.lo);

// ---------- 国家 ----------
const rules = {};
for (const r of $('解析国家表').all().map(i => i.json)) {
  const c = String(r['国家'] ?? '').trim();
  if (!c) continue;
  rules[c] = {
    是否欧盟: String(r['是否欧盟'] ?? '').trim() === '是',
    欧盟税额: num(r['欧盟税额$']) ?? 0,
    订单附加费: num(r['订单附加费']) ?? 0,
    服务费覆盖: num(r['服务费覆盖']),
  };
}

const P = {};
for (const r of $('解析全局参数').all().map(i => i.json)) {
  const k = String(r['参数键'] ?? '').trim();
  if (k) P[k] = num(r['参数值']);
}
const params = {
  FX: P['USD_CNY'] ?? 6.6,
  MULT: P['DEFAULT_SERVICE_FEE'] ?? 1.1,
  ROUND_N: P['BILL_ROUND'] ?? 2,
  EU_TAX_BASE: P['EU_TAX_BASE'] ?? 3.33,
  EU_TOPUP_PRICE: P['EU_TOPUP_PRICE'] ?? 2.3,
  CUSTOMER_NO: P['CUSTOMER_NO'] ?? '',
  CUSTOMER_NAME: P['CUSTOMER_NAME'] ?? '',
  ACCOUNT_MANAGER: P['ACCOUNT_MANAGER'] ?? '',
};

// ④ 需要的数组形态
const ratesArr = [];
for (const arr of byCountry.values()) for (const s of arr) ratesArr.push(s);
const rulesArr = Object.entries(rules).map(([c, v]) => ({
  国家: c, isEU: v.是否欧盟, surcharge: v.订单附加费, service: v.服务费覆盖, 税额: v.欧盟税额,
}));

return [{
  json: {
    products, rulesMap: rules, params,
    rates: ratesArr, rules: rulesArr,
    rateSegs: Object.fromEntries([...byCountry].map(([c, arr]) => [c, arr])),
    productMissing, rateMissing,
    counts: { 商品前缀: Object.keys(products).length, 运价段: ratesArr.length,
              国家: Object.keys(rules).length, 有运价国家: byCountry.size },
  },
}];

// ============================================================================
// ② 订单匹配配置（v6：直接按 SKU 前缀取商品参数）
// ============================================================================
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const idx = $('① 建配置索引').first().json;
const products = idx.products || {};
const prefixes = Object.keys(products).sort((a, b) => b.length - a.length);

const matchPrefix = (sku) => {
  const s = String(sku || '').trim();
  for (const p of prefixes) {
    if (s === p || s.startsWith(p + '-') || s.startsWith(p + '_')) return p;
  }
  return null;
};
const isNonGoods = (r) =>
  String(r.SKU || '').toUpperCase().startsWith('SHIP') && !String(r['原始图片'] || '').trim();

let inputRows = [];
try {
  inputRows = $('合并澳洲分区').all().map(i => i.json).filter(r => r && r.SKU);
} catch (e) {
  inputRows = $input.all().map(i => i.json).filter(r => r && r.SKU);
}
if (!inputRows.length) throw new Error('上游没有订单明细');

const missSku = new Map();
const blockedBySku = new Set();
const blockedByCfg = new Set();
const orderInfo = new Map();
const billedWeight = new Map();
const rows = [];

for (const r of inputRows) {
  const txn = r['交易编号'];
  const qty = num(r['商品数量']) ?? 1;

  let country = String(r['国家中文'] || '').trim();
  if (country === '美国' && String(r['物流渠道'] || '').includes('岛屿')) country = '美国（偏远）';
  if (country === '澳大利亚') {
    const zone = r['澳洲分区'];
    if (zone !== null && zone !== undefined && zone !== '') country = `澳大利亚（${Number(zone)}区）`;
  }
  orderInfo.set(txn, { 国家: country, SKU: r.SKU, 商品名称: r['商品名称'] || '' });

  const hit = matchPrefix(r.SKU);
  const prod = hit ? products[hit] : null;
  const nonGoods = isNonGoods(r);

  if (!hit) {
    blockedBySku.add(txn);
    const guess = String(r.SKU).split('_')[0].split('-').slice(0, 2).join('-');
    const m = missSku.get(guess) || { 标识: guess, 订单: new Set(), 行: 0, SKU: new Set(), 商品名称: new Set(), 国家: new Set() };
    m.订单.add(txn); m.行 += 1; m.SKU.add(r.SKU);
    if (r['商品名称']) m.商品名称.add(String(r['商品名称']).trim());
    m.国家.add(country);
    missSku.set(guess, m);
  } else if (!(prod && prod.采购价 !== null && prod.重量 !== null)) {
    blockedByCfg.add(txn);
  }

  const rowWt = nonGoods ? 0 : Math.round(((prod && prod.重量) ?? 0.17) * qty * 1000) / 1000;
  const okCfg = Boolean(prod) && prod.采购价 !== null && prod.重量 !== null;
  const billable = okCfg && !nonGoods;
  if (billable) billedWeight.set(txn, Math.round(((billedWeight.get(txn) || 0) + rowWt) * 1000) / 1000);

  rows.push({
    ...r, 国家: country, 前缀: hit || '', 商品中文名: (prod && prod.商品中文名) || '', 非实物: nonGoods, 行重量: rowWt, 可计费: billable,
    cfg: prod ? {
      ok: okCfg,
      组: hit,
      重量: prod.重量,
      采购价: prod.采购价,
      偏远采购价: null,
      国内运费: prod.国内运费,
      偏远国内运费: null,
      服务费: prod.服务费,
      服务费_美国: null,
      运价覆盖_国家: null,
      运价覆盖_公斤价: null,
      运价覆盖_挂号费: null,
      账单固定金额: null,
    } : null,
  });
}

const orderIndex = [...new Map(rows.map(r => [r['交易编号'], {
  交易编号: r['交易编号'], SKU: r.SKU, 前缀: r.前缀, 商品中文名: r.商品中文名,
  商品名称: r['商品名称'] || '', 国家: r.国家,
}])).values()];

return [{
  json: {
    rows,
    missSku: [...missSku.values()].map(m => ({ ...m, 订单: [...m.订单], SKU: [...m.SKU], 商品名称: [...m.商品名称], 国家: [...m.国家] })),
    blockedBySku: [...blockedBySku],
    blockedByCfg: [...blockedByCfg],
    cfgIncomplete: idx.productMissing || [],
    orderInfo: [...orderInfo.entries()].map(([txn, v]) => ({ txn, 国家: v.国家 })),
    billedWeight: [...billedWeight.entries()].map(([txn, w]) => ({ txn, w })),
    orderIndex,
    usedPrefixes: [...new Set(rows.map(r => r.前缀).filter(Boolean))],
    usedCountries: [...new Set(rows.map(r => r.国家).filter(Boolean))],
  },
}];

// ③ 运价匹配（v7：国家 + 整单重量 → 重量段；上下界都包含）
const prev = $('② 订单匹配配置').first().json;
const idx = $('① 建配置索引').first().json;
const segs = idx.rateSegs || {};

const blocked = new Set([...(prev.blockedBySku || []), ...(prev.blockedByCfg || [])]);
const weightOf = new Map((prev.billedWeight || []).map(x => [x.txn, x.w]));
const infoOf = new Map((prev.orderInfo || []).map(x => [x.txn, x.国家]));
const rows = prev.rows || [];

const byOrder = new Map();
for (const r of rows) {
  if (!byOrder.has(r['交易编号'])) byOrder.set(r['交易编号'], []);
  byOrder.get(r['交易编号']).push(r);
}

const missRate = new Map();
const orderRate = [];

for (const [txn, list] of byOrder) {
  const country = infoOf.get(txn);
  const w = weightOf.get(txn) ?? 0;

  if (w <= 0) {
    orderRate.push({ txn, 国家: country, 计费重量: 0, 段价: null, 段挂号费: null, groups: [], skip: true, 固定重量: 0 });
    continue;
  }

  const arr = segs[country] || [];
  const seg = arr.find(x => x.lo <= w && w <= x.hi) || null;

  if (!seg) {
    blocked.add(txn);
    const k = `${country}|${w}`;
    const m = missRate.get(k) || { 国家: country, 重量: w, 订单: new Set(),
      现有: arr.length ? arr.map(x => `${x.lo}-${x.hi}`).join('、') : '该国家没有运价' };
    m.订单.add(txn);
    missRate.set(k, m);
    orderRate.push({ txn, 国家: country, 计费重量: w, 段价: null, 段挂号费: null, groups: [], missing: true, 固定重量: 0 });
    continue;
  }

  const groups = new Map();
  let billable = 0;
  for (const r of list) {
    if (!r.可计费) continue;
    billable += r.行重量;
    const gk = `${seg.p}|${seg.fee}`;
    const g = groups.get(gk) || { 价: seg.p, 挂号费: seg.fee, 重量: 0, 覆盖: false };
    g.重量 = Math.round((g.重量 + r.行重量) * 1000) / 1000;
    groups.set(gk, g);
  }

  orderRate.push({
    txn, 国家: country, 计费重量: w,
    段价: seg.p, 段挂号费: seg.fee,
    固定重量: 0, 固定段价: null, 固定段挂号费: null,
    groups: [...groups.values()],
  });
}

return [{
  json: {
    ...prev,
    orderRate,
    missRate: [...missRate.values()].map(m => ({ ...m, 订单: [...m.订单] })),
    blocked: [...blocked],
  },
}];

// ============================================================================
// ④ 逐行计价：运费 / 挂号费 / 成本 / 国内运费 / 服务费 / 附加费 / 欧盟税
//   输出：每行明细（detail）
// ============================================================================
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const prev = $('③ 运价匹配').first().json;
const idx = $('① 建配置索引').first().json;
const P = idx.params || {};
const FX = P.FX ?? 6.65;
const EU_TAX = P.EU_TAX ?? 3.33;
const MULT = P.MULT ?? 1.15;

const rows = prev.rows || [];
const rules = new Map((idx.rules || []).map(r => [r.国家, r]));
const margins = new Map();
for (const s of (idx.rates || [])) {
  if (s.毛利 !== null && s.毛利 !== undefined && !margins.has(s.国家)) margins.set(s.国家, s.毛利);
}

// 订单 → 行
const byOrder = new Map();
for (const r of rows) {
  if (!byOrder.has(r['交易编号'])) byOrder.set(r['交易编号'], []);
  byOrder.get(r['交易编号']).push(r);
}
const orderRate = new Map((prev.orderRate || []).map(o => [o.txn, o]));
const blockedSet = new Set(prev.blocked || []);   // 阻断单不计入汇总

const detail = [];
const totals = { 运费: 0, 挂号费: 0, 成本: 0, 国内运费: 0, 履行价: 0 };

for (const [txn, list] of byOrder) {
  const o = orderRate.get(txn) || {};
  const country = o.国家 || '';
  const rule = rules.get(country) || {};
  const groups = o.groups || [];
  const 段价 = o.段价 ?? null;

  // 整单运费：Σ(组价×组重量) + Σ(每组挂号费)
  let 整单行运费 = 0, 整单挂号费 = 0, 覆盖差异 = 0;
  const 覆盖明细 = [];
  for (const g of groups) {
    整单行运费 += g.价 * g.重量;
    整单挂号费 += g.挂号费;
    if (段价 !== null && g.价 !== 段价) {
      覆盖差异 += (g.价 - 段价) * g.重量;
      覆盖明细.push({ 价: g.价, 重: g.重量, 挂号费: g.挂号费 });
    }
  }
  整单行运费 = Math.round(整单行运费 * 100) / 100;
  整单挂号费 = Math.round(整单挂号费 * 100) / 100;
  覆盖差异 = Math.round(覆盖差异 * 100) / 100;

  // 运费行 = 同单第一个非固定金额商品
  const freightRow = list.find(x => x.cfg && x.cfg.账单固定金额 === null) || list[0];

  // 服务费：国家表「服务费覆盖」优先 > 商品表（美国列/普通列）> 运价表毛利 > 默认
  const isUS = country.startsWith('美国');
  const svcOf = (c) => {
    // 1) 国家表配置优先
    if (rule.service !== null && rule.service !== undefined && rule.service !== '') {
      return Number(rule.service);
    }
    // 2) 商品表
    let v = null;
    if (c) {
      if (isUS && c.服务费_美国 !== null) v = c.服务费_美国;
      else if (c.服务费 !== null) v = c.服务费;
    }
    // 3) 运价表毛利 4) 默认
    return v === null ? (margins.get(country) ?? MULT) : v;
  };

  // 国内运费份数：同单同 SKU 合并后 ceil(件数 / N)
  const skuQty = new Map();
  const groupKey = (r) => (r.cfg && r.cfg.组) ? r.cfg.组 : r.SKU;   // 同一配置行的别名合并
  for (const r of list) {
    const k = groupKey(r);
    skuQty.set(k, (skuQty.get(k) || 0) + (num(r['商品数量']) ?? 1));
  }
  const seenSku = new Set();
  const isFirstRow = new Map();
  list.forEach((r, i) => isFirstRow.set(r, i === 0));

  for (const r of list) {
    const c = r.cfg;
    const qty = num(r['商品数量']) ?? 1;
    const isFixed = c ? c.账单固定金额 !== null : false;
    const isFreight = r === freightRow;

    // 运费只落一次
    let 行运费 = isFreight ? 整单行运费 : 0;
    let 挂号费 = isFreight ? 整单挂号费 : 0;

    // 固定金额商品：账单按固定价，但运费列按「运价覆盖 → 运价段」写出来
    let 固定运费 = null, 固定单价 = null, 固定挂号 = null;
    if (isFixed && isFreight) {
      const fw = o.固定重量 ?? 0;
      const useOv = c.运价覆盖_国家 && c.运价覆盖_国家 === country && c.运价覆盖_公斤价 !== null;
      固定单价 = useOv ? c.运价覆盖_公斤价 : (o.固定段价 ?? null);
      固定挂号 = useOv ? (c.运价覆盖_挂号费 !== null ? c.运价覆盖_挂号费 : (o.固定段挂号费 ?? null))
                       : (o.固定段挂号费 ?? null);
      if (固定单价 !== null) {
        固定运费 = Math.round((固定单价 * fw + (固定挂号 || 0)) * 100) / 100;
        行运费 = 固定运费 - (固定挂号 || 0);
        挂号费 = 固定挂号 || 0;
      }
    }

    const 运费 = (固定运费 !== null) ? 固定运费
      : Math.round((行运费 + 挂号费) * 100) / 100;

    // 成本（偏远单用偏远价）
    const 采购价 = r.非实物 ? 0 : ((c && (country === '美国（偏远）' && c.偏远采购价 !== null)
      ? c.偏远采购价 : (c ? c.采购价 : null)) ?? 0);
    const 成本 = Math.round(qty * 采购价 * 100) / 100;

    // 国内运费
    const 国内单价 = r.非实物 ? 0 : ((c && (country === '美国（偏远）' && c.偏远国内运费 !== null)
      ? c.偏远国内运费 : (c ? c.国内运费 : null)) ?? 0);
    const gk = groupKey(r);
    const first = !seenSku.has(gk);
    seenSku.add(gk);
    // 国内运费按件数计（不再按「每计费单位件数」折算份数）
    const 份数 = (r.非实物 || !first) ? 0 : (skuQty.get(gk) || 0);
    const 国内运费合计 = Math.round(国内单价 * 份数 * 100) / 100;

    const 服务费 = svcOf(c);
    const 附加费 = isFirstRow.get(r) ? (rule.surcharge || 0) : 0;
    const 固定金额合计 = isFixed ? Math.round(c.账单固定金额 * 份数 * 100) / 100 : 0;

    // 人民币保留 4 位（客户表是 62.1378 这种精度，过早四舍五入会让账单差 0.01）
    let 人民币 = Math.round((运费 + 成本 + 国内运费合计 + 附加费) * 服务费 * 10000) / 10000;
    if (isFixed) 人民币 = Math.round(固定金额合计 * FX * 100) / 100;
    const 美元 = 人民币 / FX;
    // 欧盟税：分拆口径 —— 先按 EU_TAX_BASE（默认 3.33），差额 EU_TOPUP_PRICE（2.3）在底部补收/PDF UHF 列
  const EU_TOPUP = P.EU_TOPUP_PRICE ?? 0;
  const EU_BASE = P.EU_TAX_BASE;
  const euTaxValue = (EU_TOPUP > 0 && EU_BASE !== null && EU_BASE !== undefined)
    ? EU_BASE
    : (rule.税额 ?? EU_TAX);
  const 欧盟税 = isFirstRow.get(r) && rule.isEU ? euTaxValue : 0;
    const 履行价 = Math.round((运费 + 成本 + 国内运费合计) * 100) / 100;

    if (!blockedSet.has(txn)) {
      totals.运费 += 运费; totals.挂号费 += 挂号费;
      totals.成本 += 成本; totals.国内运费 += 国内运费合计; totals.履行价 += 履行价;
    }

    detail.push({
      交易编号: txn, 订单编号: r['订单编号'] || '', 国家: country,
      国家二字码: r['国家二字码'] || '',
      物流公司: r['物流公司'] || '', 物流渠道: r['物流渠道'] || '',
      内部单号: r['内部单号'] || '', 邮政编码: r['邮政编码'] || '', 图片: r['原始图片'] || '',
      SKU: r.SKU, 前缀: r.前缀 || '', 件数: qty, 单件重量: c ? c.重量 : null,
      行重量: r.行重量, 整单重量: o.计费重量 ?? null, 计费重量: o.计费重量 ?? null,
      整单模式: true, 运费行: isFreight,
      公斤价: isFreight ? (固定单价 !== null ? 固定单价 : (段价 ?? (groups[0] ? groups[0].价 : null))) : null,
      挂号费: isFreight ? 挂号费 : (c ? c.运价覆盖_挂号费 : null),
      固定金额单: Boolean(isFixed),
      覆盖差价: 覆盖差异, 覆盖明细,
      行运费, 挂号费合计: 挂号费, 运费,
      采购价, 成本, 国内运费单价: 国内单价, 国内运费份数: 份数, 国内运费合计,
      履行价, 服务费, 附加费, 固定金额合计,
      账单固定金额: c ? c.账单固定金额 : null,   // 写表用：判断该行是否为固定金额商品
      人民币, 美元, 欧盟税,
      非实物: r.非实物, 缺配置: !c || !c.ok, 缺运价: Boolean(o.missing),
    });
  }
}
for (const k of Object.keys(totals)) totals[k] = Math.round(totals[k] * 100) / 100;

return [{ json: { ...prev, detail, totals } }];

// ============================================================================
// ⑤ 订单汇总：账单金额（Σ美元 + 欧盟税）、毛利、总额
//   阻断单不出金额（账单记 0）
// ============================================================================
const prev = $('④ 逐行计价').first().json;
const idx = $('① 建配置索引').first().json;
const P = idx.params || {};
const FX = P.FX ?? 6.65;
const ROUND_N = P.ROUND_N ?? 2;

const detail = prev.detail || [];
const blocked = new Set(prev.blocked || []);

// 订单 → 行
const byOrder = new Map();
for (const x of detail) {
  if (!byOrder.has(x.交易编号)) byOrder.set(x.交易编号, []);
  byOrder.get(x.交易编号).push(x);
}

const usdOf = new Map(), costOf = new Map(), taxOf = new Map();
for (const x of detail) {
  usdOf.set(x.交易编号, (usdOf.get(x.交易编号) || 0) + x.美元);
  costOf.set(x.交易编号, (costOf.get(x.交易编号) || 0) + x.履行价);
  if (x.欧盟税) taxOf.set(x.交易编号, x.欧盟税);
}

const billOf = new Map();
for (const [txn, usd] of usdOf) {
  if (blocked.has(txn)) { billOf.set(txn, 0); continue; }
  const tax = taxOf.get(txn) || 0;
  billOf.set(txn, Math.round((usd + tax) * Math.pow(10, ROUND_N)) / Math.pow(10, ROUND_N));
}

let 毛利 = 0;
for (const [txn, bill] of billOf) {
  if (blocked.has(txn)) continue;
  毛利 += Math.round((bill * FX - (costOf.get(txn) || 0)) * 100) / 100;
}

for (const x of detail) {
  x.订单美元合计 = Math.round((usdOf.get(x.交易编号) || 0) * 1e6) / 1e6;
  x.账单金额 = billOf.get(x.交易编号);
  x.订单履行价 = Math.round((costOf.get(x.交易编号) || 0) * 100) / 100;
  x.毛利 = Math.round((x.账单金额 * FX - x.订单履行价) * 100) / 100;
}

const totals = { ...(prev.totals || {}) };
totals.人民币 = Math.round(detail.reduce((s, x) => s + x.人民币, 0) * 100) / 100;
totals.账单 = Math.round([...billOf.entries()].filter(([t]) => !blocked.has(t))
  .reduce((s, [, v]) => s + v, 0) * 100) / 100;
totals.毛利 = Math.round(毛利 * 100) / 100;

return [{
  json: {
    ...prev,
    detail,
    totals,
    billOf: [...billOf.entries()].map(([txn, bill]) => ({ txn, bill })),
  },
}];

// ⑥ 异常汇总（v7：运价按国家+重量段）
const prev = $('⑤ 订单汇总').first().json;
const idx = $('① 建配置索引').first().json;
const detail = prev.detail || [];
const blocked = new Set(prev.blocked || []);
const rows = prev.rows || [];
const OI = new Map((prev.orderIndex || []).map(o => [o.交易编号, o]));
const infoOf = (t) => OI.get(t) || {};

const skuList = (prev.missSku || []).slice().sort((a, b) => b.订单.length - a.订单.length);
const usedPrefixes = new Set(prev.usedPrefixes || rows.map(r => r.前缀).filter(Boolean));
const cfgList = (prev.cfgIncomplete || []).filter(x => usedPrefixes.has(x.前缀));
const rateList = (prev.missRate || []).slice().sort((a, b) => b.订单.length - a.订单.length);

const auMissing = new Map();
for (const r of rows) {
  if (String(r['国家中文'] || '').trim() !== '澳大利亚') continue;
  if (r['澳洲分区'] !== null && r['澳洲分区'] !== undefined && r['澳洲分区'] !== '') continue;
  const pc = String(r['澳洲邮编'] || r['邮政编码'] || '').replace(/\D/g, '').padStart(4, '0').slice(-4) || '(空)';
  const m = auMissing.get(pc) || { 邮编: pc, 订单: new Set() };
  m.订单.add(r['交易编号']);
  auMissing.set(pc, m);
}
const auList = [...auMissing.values()].map(m => ({ 邮编: m.邮编, 订单: [...m.订单] }));

const rulesMap = idx.rulesMap || {};
const missCountry = (prev.usedCountries || []).filter(c => !rulesMap[c]).map(cn => {
  const list = (prev.orderIndex || []).filter(o => o.国家 === cn);
  return { 国家: cn, 订单数: list.length,
           商品: [...new Set(list.map(o => o.商品中文名 || '').filter(Boolean))].slice(0, 3),
           例SKU: (list[0] || {}).SKU || '', 例交易号: (list[0] || {}).交易编号 || '' };
});
const emptyRate = (idx.rateMissing || []);
const cfgDetail = cfgList.map(m => {
  const list = (prev.orderIndex || []).filter(o => o.前缀 === m.前缀);
  return { 前缀: m.前缀, 商品中文名: m.商品中文名, 缺: m.缺, 订单数: list.length,
           国家: [...new Set(list.map(o => o.国家).filter(Boolean))].slice(0, 3),
           例SKU: (list[0] || {}).SKU || '', 例交易号: (list[0] || {}).交易编号 || '' };
});
const listedOrders = new Set([
  ...(prev.missSku || []).flatMap(m => m.订单 || []),
  ...(prev.missRate || []).flatMap(m => m.订单 || []),
]);
const leftover = [...blocked].filter(t => !listedOrders.has(t)).map(t => {
  const o = infoOf(t);
  return { 交易编号: t, SKU: o.SKU || '', 前缀: o.前缀 || '', 商品中文名: o.商品中文名 || '',
           商品名称: o.商品名称 || '', 国家: o.国家 || '' };
});

const missingCount = skuList.length + cfgDetail.length + rateList.length + auList.length
  + missCountry.length + emptyRate.length + leftover.length;

const allOrders = new Set(rows.map(r => r['交易编号']));
return [{
  json: {
    ok: true,
    totalOrders: allOrders.size, totalRows: rows.length,
    blockedOrders: blocked.size, missingCount,
    missingSku: skuList.length, missingCfg: cfgDetail.length, missingRate: rateList.length,
    missingAu: auList.length, missingCountry: missCountry.length, emptyRate: emptyRate.length,
    leftover: leftover.length,
    missSkuDetail: skuList.map(m => ({ 标识: m.标识, 订单数: m.订单.length, SKU样例: m.SKU,
      商品名称: m.商品名称 || [], 国家: m.国家 || [], 例交易号: (m.订单 || [])[0] || '' })),
    cfgDetail, missCountryDetail: missCountry, emptyRateDetail: emptyRate,
    missRateDetail: rateList.map(m => ({ 国家: m.国家, 重量: m.重量, 现有: m.现有, 订单数: m.订单.length,
      例SKU: (infoOf(m.订单[0]) || {}).SKU || '', 例交易号: (m.订单 || [])[0] || '' })),
    auMissingDetail: auList, leftoverDetail: leftover,
    totals: prev.totals || {}, params: idx.params || {}, detail,
    message: `缺失 ${missingCount} 类`,
  },
}];

// ============================================================================
// 解析表单输入：交易编号归一（兼容中英文逗号）+ 校验 + 备注清洗
//   输出：${mode} = numbers | dates，以及文件名后缀 noteSuffix
// ============================================================================
// webhook 入口会把数据放在 body 里，表单入口则是平铺字段
const j = ($json && $json.body) ? $json.body : ($json || {});
// 兼容两种字段命名（用户自建表单 / 新表单）
const pick = (...keys) => {
  for (const k of keys) {
    const v = j[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
};
const rawNo = pick('交易编号', '订单编号', 'id', 'salesRecordNumbers', 'platformOrderIds');
const rawNote = pick('备注', 'remark', 'note');
const rawPrev = pick('上期未付', 'prev_balance', 'previousBalance', 'preBalance');
const 上期余额 = Number(String(rawPrev).replace(/[^0-9.\-]/g, '')) || 0;
const startDate = pick('订单创建开始日期', '开始日期', 'startDate').trim();
const endDate = pick('订单创建结束日期', '结束日期', 'endDate').trim();

// ---------- 交易编号：吃所有分隔符 ----------
const list = rawNo
  .normalize('NFKC')                       // 全角数字/逗号 → 半角
  .replace(/["'“”‘’]/g, '')
  .split(/[,，、;；|\s]+/)                  // 中英逗号、顿号、分号、竖线、空格、换行
  .map(s => s.trim())
  .filter(Boolean);

const uniq = [...new Set(list)];
// 交易编号允许字母/数字/横线/下划线/点（不同店铺格式不同），不再要求纯数字
const bad = uniq.filter(s => !/^[A-Za-z0-9][A-Za-z0-9\-_.]{0,39}$/.test(s));
const dupCount = list.length - uniq.length;
const numbers = uniq.filter(s => /^[A-Za-z0-9][A-Za-z0-9\-_.]{0,39}$/.test(s));   // 只留合法单号

// 每 10 个一批，分批查询（不再报错）
const BATCH = 10;
const chunks = [];
for (let i = 0; i < numbers.length; i += BATCH) chunks.push(numbers.slice(i, i + BATCH));

// ---------- 备注 → 文件名后缀 ----------
let note = rawNote.normalize('NFKC').trim()
  .replace(/[\\/:*?"<>|]/g, '_')
  .replace(/\.{2,}/g, '_')
  .replace(/\s+/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '')
  .slice(0, 20);
const noteSuffix = note ? `_${note}` : '';

// ---------- 校验 ----------
const errors = [];
if (!numbers.length && !(startDate && endDate)) {
  errors.push('请填写「开始日期 + 结束日期」，或者填写「交易编号」');
}
if (bad.length) {
  errors.push(`这些交易编号含非法字符（只能字母/数字/-/_/.）：${bad.slice(0, 5).join('、')}`);
}
if (startDate && endDate && startDate > endDate) {
  errors.push(`结束日期（${endDate}）不能早于开始日期（${startDate}）`);
}

const mode = numbers.length ? 'numbers' : 'dates';

// 提交交易编号时：查询窗口固定为「今天往前 7 天」（ERP 单号查询不带日期，这里只做记录/展示）
let 窗口开始 = startDate, 窗口结束 = endDate, 窗口天数 = 0;
if (mode === 'numbers') {
  const now = new Date(Date.now() + 8 * 3600 * 1000);           // 北京时间
  const p2 = (x) => String(x).padStart(2, '0');
  const fmt = (d) => `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}`;
  // 19 点前查近 7 天，19 点后查近 30 天
  const hour = now.getUTCHours();
  窗口天数 = hour < 19 ? 7 : 30;
  窗口结束 = fmt(now);
  窗口开始 = fmt(new Date(now.getTime() - 窗口天数 * 86400000));
}

return [{
  json: {
    ok: errors.length === 0,
    errors,
    mode,
    交易编号: numbers,
    numbersString: numbers.join(','),
    chunks,
    批次数: chunks.length,
    单号数: numbers.length,
    开始日期: startDate,
    结束日期: endDate,
    窗口开始,
    窗口结束,
    时间窗口: mode === 'numbers' ? `${窗口开始} ~ ${窗口结束}（最近 ${窗口天数} 天）` : `${startDate} ~ ${endDate}`,
    窗口天数,
    备注: note,
    上期余额,
    noteSuffix,
    去重数: dupCount,
    提示: [
      mode === 'numbers'
        ? `已按交易编号查询（忽略日期）：${numbers.length} 个单号，分 ${chunks.length} 批（每批最多 10 个）`
        : '已按时间段查询',
      dupCount ? `自动去重 ${dupCount} 个` : '',
      bad.length ? `忽略 ${bad.length} 个非数字输入：${bad.slice(0, 3).join('、')}` : '',
      note ? `文件名后缀：${noteSuffix}` : '未填备注',
    ].filter(Boolean),
  },
}];

// 通知①：订单已导出（含文件位置）
const p = $('整理订单Excel').first().json;
let win = '';
try { win = $('解析表单输入').first().json.时间窗口 || ''; } catch (e) {}
