// return JSON.parse($input.first().json.data).orderDataList
const orderList = $input.all().map(item=>{
  return JSON.parse(item.json.data).orderDataList
}).flat(Infinity)

// 兼容表单入口和 webhook 入口：统一从「解析表单输入」取参数
let form = {};
try { form = $('解析表单输入').first().json; } catch (e) { form = {}; }
const ids = Array.isArray(form['交易编号']) ? form['交易编号'].map(x => String(x)) : (form['numbersString'] ? String(form['numbersString']).split(',') : []);
const startDate = form['开始日期'] || '';
const endDate = form['结束日期'] || '';

return (ids.length !== 0
  ? orderList.filter(item => ids.includes(String(item.salesRecordNumber)))
  : orderList.filter(item => {
      const t = new Date(item.createDate);
      return (!startDate || t > new Date(startDate)) && (!endDate || t < new Date(endDate));
    }));

return $input.all().map(item=>{

  const html = item.json.cansend1logisticsHtml || '';
  const remark_html = item.json.remark

  // 1. 提取物流渠道文本 (优先取标签内文本，兜底取 title 属性)
  const chMatch = html.match(/logisticsChannelText[^>]*>([^<]*)<\/p>/) || 
                  html.match(/logisticsChannelText[^>]*title="([^"]+)"/);
  const rawChannel = chMatch ? (chMatch[1] || chMatch[2] || '').trim() : '';

  // 2. 分离【】内外的物流商和渠道
  const carrierMatch = rawChannel.match(/【([^】]+)】/);

  // 3. 通用单号提取函数 (自动去除 &nbsp;、空格、换行、斜杠等杂数据)
  const getTrack = (field) => {
    const m = html.match(new RegExp(`data-field="${field}"[^>]*>([^<]*)</a>`));
    return m ? m[1].replace(/&nbsp;|[\s/]/g, '') : '';
  };

  // 4. 提取订单备注纯文本 (去除 HTML 标签，保留内部正常空格，首尾去空)
  const remMatch = html.match(/orderRemark[^>]*>([\s\S]*?)<\/div>/);
  const remark = remMatch ? remMatch[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim() : '';

  return {
    "交易编号": item.json.salesRecordNumber,
    "订单编号": item.json.platformOrderId,
    "国家中文": item.json.countryCodeCn,
    "国家二字码": item.json.countryCodeEn,
    "邮政编码": item.json.postCode,
    "实际运费": item.json.shippingFee,
    "物流公司": carrierMatch ? carrierMatch[1].trim() : '',
    "物流渠道": rawChannel.replace(/【[^】]+】/g, '').trim(),
    "内部单号": getTrack('trackNumber1'),
    "订单备注": remark,
    "stock_id": item.json.id,
    "tableBase": item.json.tableBase,
    "商品个数": (() => {
      const t = String(item.json.order_ellipsis_title || item.json.order_ellipsis_other_title || '');
      const m = t.match(/商品个数[:：]\s*(\d+)/);
      return m ? Number(m[1]) : null;
    })()
  }
})

// 按订单自带的 tableBase 分组，每组内再按 50 个一批（马帮的订单分在多张表里）
const BATCH = 50;
const groups = new Map();
for (const it of $('Code in JavaScript2').all()) {
  const j = it.json || {};
  if (!j.stock_id) continue;
  const tb = String(j.tableBase || 1);
  if (!groups.has(tb)) groups.set(tb, new Set());
  groups.get(tb).add(String(j.stock_id));
}
const out = [];
for (const [tb, set] of [...groups.entries()].sort()) {
  const ids = [...set];
  for (let i = 0; i < ids.length; i += BATCH) {
    out.push({ json: { tableBase: Number(tb), ids: ids.slice(i, i + BATCH).join(','), 本批数量: ids.slice(i, i + BATCH).length } });
  }
}
if (!out.length) throw new Error('没有拿到 stock_id');
return out;

