}
return [{ json: { success: true, order_list_html_header: out } }];

// 把抓包拿到的订单商品明细解析成数组并扁平化（字段和以前用接口时保持一致）
const orders = $('Code in JavaScript2').all().map(i => i.json);
const resp = $input.first().json || {};
const htmlMap = resp.order_list_html_header || {};

const BAD_TITLE = /缺货|平台链接|更换|权限|仓库|销量|订单列表|复制|提示|查看原图|采购链接/;

const rows = [];
for (const o of orders) {
  const html = String(htmlMap[String(o.stock_id)] || htmlMap[o.stock_id] || '');
  const trs = [...html.matchAll(/<tr\b[\s\S]*?<\/tr>/g)].map(m => m[0]);

  for (const tr of trs) {
    const sku = (tr.match(/class="text-accent SkuNumber"[^>]*>([^<]+)</) || [])[1];
    if (!sku) continue;

    const qty = Number((tr.match(/stock-product-nums">(\d+)</) || [])[1] || 1);

    // 原始图片
    const img = (tr.match(/originalPictureUrl"[^>]*value="([^"]+)"/) || [])[1] || '';
    const lineId = (tr.match(/data-orderItemId="(\d+)"/) || [])[1]
      || (tr.match(/data-order-item-id="(\d+)"/) || [])[1]
      || (tr.match(/id="SkuNumber_\d+(\d{6,})"/) || [])[1] || '';

    // 商品名称（商品标题）
    let title = '';
    for (const m of (tr.match(/title="([^"]+)"/g) || [])) {
      const v = m.slice(7, -1).trim();
      if (!v || BAD_TITLE.test(v)) continue;
      if (v.length > 4 && !/^\d+$/.test(v)) { title = v; break; }
    }

    // 商品成本（订单列表里的“成本价”单元格，第一个数字是单价）
    let cost = null;
    const costCell = (tr.match(/data-listbtn="更新成本价"[^>]*>([\d.]+)</) || [])[1]
      || (tr.match(/data-field="sellPrice"[\s\S]{0,120}?>([\d.]+)</) || [])[1];
    if (costCell) { const n = Number(costCell); if (Number.isFinite(n)) cost = n; }

    rows.push({
      "交易编号": o.交易编号,
      "订单编号": o.订单编号,
      "原始图片": img,
      "商品数量": qty,
      "SKU": String(sku).trim(),
      "行ID": lineId,
      "商品名称": title,
      "商品成本": cost,
      "国家中文": o.国家中文,
      "国家二字码": o.国家二字码,
      "物流公司": o.物流公司,
      "物流渠道": o.物流渠道,
      "内部单号": o.内部单号,
      "实际运费": o.实际运费,
      "订单备注": o.订单备注,
      "邮政编码": o.邮政编码,
    });
  }
}
return rows;
